source.exploreUrl:
@js:
sort=[];
push=(title,url,type1,type2)=>sort.push({
		title: title,
		url: url,
		style: {
				layout_flexGrow: type1,
				layout_flexBasisPercent: type2
			}
	});

function fl() {			
			url = `${host}/category`;
    return  JSON.parse(java.ajax(url)).body.data; 		
		}

		fl().map($=>{				
 			push($.name, null, 1, 1);
 			list = $.items;
 list.map(($,index)=>{	   	    
 	    	title = $.name;
	url = `${host}/category?categoryId=${$.categoryId}&resourcesId=${$.resourcesId}&page={{page}}`;			 
			if(index+1 <= list.length - list.length%3)
			 {	push(title, url, 1, 0.25);}
				else{ push(title, url, 0, 0.29);}
        });   
  });

JSON.stringify(sort);

