function getHuatiUrl(id,name){
    return `https://m.weibo.cn/api/container/getIndex?containerid=231522type%3D${id}%26t%3D10%26q%3D%23${name}%23&isnewpage=1&luicode=10000011&lfid=100103type%3D1%26q%3D${name}&page_type=searchall&page=1`;
}

function getUserSort(id,name){
	const {java} = this;
         let m = "https://m.weibo.cn";
         let nname = "👤"+name;
         let url = m+ "/api/container/getIndex?containerid=230413"+id+"_-_WEIBO_SECOND_PROFILE_WEIBO&page_type=03&since_id=";
         let userTopUrl = m+"/api/container/getIndex?type=uid&value="+ id;
            try{
                let userJsonData = java.ajax(userTopUrl);
                userJsonData = JSON.parse(userJsonData||"{}");
              if(userJsonData.ok===1){
                  let tabsInfo = userJsonData.data.tabsInfo;
                  let tabs = tabsInfo.tabs;
                  let uu = {}
                  let base = m+"/api/container/getIndex?type=uid&value=";
                  uu[nname+"的微博"] = url;
                  tabs.forEach(x=>{
                      switch(x.title){
                           case "精选":
                               url =  base+id+"&containerid=231002"+id+"_-_HOTMBLOG&page=1"
                            break;
                            case "视频":       
                            case "相册":
                                url = base+id+"&containerid="+x.containerid+"&since_id=";
                             break;
                         }
                       x.title!=="微博"? uu[x.title] = url:null
                  });
                  url = JSON.stringify(uu);
              }
              }catch(e){
              	java.log(e)
              }
              return url
}

function getSuperUrl(name,url){
 	  const {java} = this;
    let jsonAjax = java.ajax(url);
    let jsonData = JSON.parse(jsonAjax);
    let channel_list = jsonData.data.pageInfo.cardlist_head_cards[0].channel_list;
    let data = {};
    channel_list.forEach(tab=>{
         let u = `https://m.weibo.cn/api/container/getIndex?containerid=`;
        if(tab.id == "feed"){
            data[name+"的📝帖子"] = u+tab.containerid+"&since_id=";
            data["📤帖子"] = u+tab.containerid.replace(/feed/,'sort_time')+"&since_id=";
            data["🔥帖子"] = u+tab.containerid.replace(/feed/,'recommend')+"&since_id=";
            data["💡帖子"] = u+tab.containerid.replace(/feed/,'soul')+"&since_id=";
        }else if(/\d+/.test(tab.id)){
            data["📝"+tab.name] = u+tab.containerid+"&since_id=";
            data["📤"+tab.name] = u+tab.containerid.replace(/comment_sort/,'status_sort')+"&since_id=";
        }else{
            data[tab.name] = u+tab.containerid+"&since_id=";
        }
    })

    return JSON.stringify(data)

}

